-- Reference seed (part 06.02): flag (OFF by default, ON in development and test), navigation and tracker rows of the common master pages, and the system rows every company sees:
-- states and union territories with their GST state codes, currencies, GST rates, common construction HSN/SAC codes, TDS/TCS sections, units of measure, payment and delivery terms, Incoterms and the lookup lists.
-- Statutory values are a starting point an accounts manager reviews; a change goes through its approval (ACCMGR then CFO).
INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, environment, enabled, created_by, source_type) VALUES ('ff.mdm.p0602', 'Part 06.02 common masters: units, GST rates, HSN/SAC, TDS sections, states, currencies and rates, banks, payment terms, lookup lists', 0, NULL, 0, 'migration', 'reference_seed');
